/*
  # Create system user and seed predefined templates/macros

  ## Overview
  1. Creates a system user in auth.users for system-level templates and macros
  2. Seeds 50 predefined radiology report templates across all modalities
  3. Seeds 25 system-level macros for common findings
  4. Adds RLS policies for all authenticated users to read system resources

  ## Templates (50)
  CT: Chest Normal, Lung Cancer/Nodule, PE, Abdomen Normal, Kidney Stone,
      Head Normal, Acute Stroke, Cervical Spine, Lumbar Spine, CT Coronary Angiography,
      PNS/Sinuses, CT Neck Soft Tissue
  MRI: Brain Normal, MS/Demyelination, Brain Tumor, Cervical Spine, Lumbar Spine,
       Knee, Shoulder, MRCP/Liver, Ankle, Hip
  X-Ray: Chest Normal, Pneumonia, Rib Fracture, Abdomen, Spine (L/S),
          Knee, Hip, Hand/Wrist
  Ultrasound: Abdomen Normal, Kidney Stone, Gallstones/Cholecystitis,
              Pelvis Normal (Female), Thyroid Normal, Obstetric 1st Tri,
              Scrotal, Carotid Doppler, DVT Lower Limb, Breast
  PET-CT: Oncology Staging
  Mammography: Normal, Suspicious Mass
  Fluoroscopy: Barium Swallow, IVP/IVU
  Nuclear Medicine: Bone Scan, HIDA/Hepatobiliary

  ## Macros (25)
  US: /us-normal-abd, /us-normal-kidney, /us-gallstones, /us-kidney-stone,
      /us-normal-thyroid, /us-normal-pelvis, /us-normal-scrotal, /us-carotid-normal,
      /us-dvt-negative, /us-normal-breast
  CT: /ct-normal-chest, /ct-normal-abd, /ct-normal-brain, /ct-normal-cspine, /ct-normal-lspine
  MRI: /mri-normal-brain, /mri-normal-knee, /mri-normal-shoulder, /mri-normal-lspine, /mri-normal-cspine
  XR: /xr-normal-chest, /xr-normal-abdomen, /xr-normal-knee, /xr-normal-hip, /xr-normal-ls
*/

-- Create system user in auth.users
INSERT INTO auth.users (
  id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
  created_at, updated_at, confirmation_token, email_change, recovery_token
) VALUES (
  '00000000-0000-0000-0000-000000000000',
  '00000000-0000-0000-0000-000000000000',
  'authenticated',
  'authenticated',
  'system@radai.internal',
  extensions.crypt(
  'system-placeholder-not-for-login',
  extensions.gen_salt('bf')
),
  now(),
  now(),
  now(),
  '',
  '',
  ''
) ON CONFLICT (id) DO NOTHING;

-- Create system profile
INSERT INTO profiles (id, name, role, specialty) VALUES
  ('00000000-0000-0000-0000-000000000000', 'System', 'system', 'general')
ON CONFLICT (id) DO NOTHING;

-- RLS policies for system resources
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'templates'
    AND policyname = 'Authenticated users can read system templates'
  ) THEN
    CREATE POLICY "Authenticated users can read system templates"
      ON templates FOR SELECT
      TO authenticated
      USING (user_id = '00000000-0000-0000-0000-000000000000');
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'macros'
    AND policyname = 'Authenticated users can read system macros'
  ) THEN
    CREATE POLICY "Authenticated users can read system macros"
      ON macros FOR SELECT
      TO authenticated
      USING (user_id = '00000000-0000-0000-0000-000000000000');
  END IF;
END $$;

