-- ─────────────────────────────────────────────────────────────
-- CT CHEST
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'CT Chest - Normal',
 'Standard normal CT chest report format',
 'CT Chest',
 '[{"id":"s1","label":"Technique","placeholder":"Helical CT of the chest was performed with intravenous contrast material in the portal venous phase. Axial images were acquired with multiplanar reformats in coronal and sagittal planes.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"LUNGS AND AIRWAYS: The trachea is central with normal calibre. The main, lobar and segmental bronchi are patent. The lungs are clear bilaterally. No consolidation, ground-glass opacity, pleural effusion, or pneumothorax. No pulmonary nodule or mass.\n\nPLEURA: No pleural effusion, thickening, or pneumothorax bilaterally.\n\nMEDIASTINUM AND HILA: The mediastinal and hilar contours are unremarkable. No pathological lymphadenopathy. The oesophagus is normal in calibre.\n\nCARDIAC AND GREAT VESSELS: The cardiac silhouette is within normal limits. The aorta is normal in calibre and contour. The pulmonary arterial trunk is normal.\n\nCHEST WALL AND DIAPHRAGM: The ribs, sternum, and thoracic spine are intact without acute fracture or suspicious lesion. The diaphragms are intact and normally positioned.\n\nVISUALISED UPPER ABDOMEN: The visualised liver, spleen, and upper renal poles appear unremarkable.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute cardiopulmonary abnormality.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Chest - Pulmonary Nodule / Lung Cancer',
 'Comprehensive format for pulmonary nodule or lung cancer with Lung-RADS and staging',
 'CT Chest',
 '[{"id":"s1","label":"Technique","placeholder":"Helical CT of the chest was performed with intravenous contrast material...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known or suspected pulmonary nodule / lung malignancy...","required":true,"type":"text"},{"id":"s3","label":"Nodule Characteristics","placeholder":"Location: [lobe, segment]\nSize: [X] mm (axial) x [X] mm (craniocaudal)\nMorphology: [solid / part-solid / ground-glass]\nMargins: [smooth / spiculated / lobulated]\nAttenuation: [HU]\nLung-RADS Category: [1/2/3/4A/4B/4X]\nComparison: [new / stable / increased from prior dated ...]","required":true,"type":"text"},{"id":"s4","label":"Findings - Lungs","placeholder":"Description of pulmonary parenchyma including full bilateral assessment...","required":true,"type":"text"},{"id":"s5","label":"Findings - Mediastinum and Hila","placeholder":"Mediastinal and hilar lymph node assessment with short-axis measurements where applicable...","required":true,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Pleura, pericardium, chest wall, osseous structures, visualised upper abdomen, adrenal glands...","required":false,"type":"text"},{"id":"s7","label":"Staging (if malignancy suspected)","placeholder":"T: \nN: \nM: \nOverall Stage:","required":false,"type":"text"},{"id":"s8","label":"Impression","placeholder":"1. [Lung-RADS X] [solid/part-solid/GGO] pulmonary nodule [lobe], measuring [X] mm...\n2. Recommendations: [CT follow-up in X months / PET-CT / tissue sampling]","required":true,"type":"text"}]'::jsonb,
 '[{"id":"c1","trigger_keyword":"lung nodule","add_section":"Nodule Characteristics","section_content":"Pulmonary nodule identified. Document: location (lobe/segment), size (axial diameter), morphology (solid/part-solid/GGO), margins (smooth/spiculated/lobulated), and Lung-RADS category."},{"id":"c2","trigger_keyword":"lung cancer","add_section":"Staging (if malignancy suspected)","section_content":"TNM staging: T (primary tumour size and local extent), N (regional nodal status), M (distant metastasis). Include overall stage group."},{"id":"c3","trigger_keyword":"metastasis","add_section":"Staging (if malignancy suspected)","section_content":"Metastatic disease identified. Sites: [specify]. Dominant lesion: [describe]."}]'::jsonb,
 false, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Chest - Pulmonary Embolism (CTPA)',
 'CT Pulmonary Angiography format for PE assessment with right heart strain evaluation',
 'CT Chest',
 '[{"id":"s1","label":"Technique","placeholder":"CT pulmonary angiography was performed following bolus IV contrast injection with bolus tracking in the main pulmonary artery. Adequate opacification of the pulmonary vasculature was achieved.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Suspected pulmonary embolism. D-dimer: [value]. Clinical probability: [low/intermediate/high - Wells score: X].","required":true,"type":"text"},{"id":"s3","label":"Pulmonary Arteries","placeholder":"Main pulmonary artery: [patent / filling defect]\nRight PA: [patent / filling defect — central / lobar / segmental / subsegmental]\nLeft PA: [patent / filling defect — central / lobar / segmental / subsegmental]\n\nIf PE present — Location: [saddle / central / lobar / segmental / subsegmental]\nEstimated clot burden: [massive / submassive / low-risk]\nLuminal occlusion: [complete / partial]","required":true,"type":"text"},{"id":"s4","label":"Right Heart Strain Assessment","placeholder":"RV/LV diameter ratio (axial): [X] (normal <1.0)\nInterventricular septum: [normal / deviated leftward / D-sign]\nContrast reflux into IVC/hepatic veins: [present / absent]\nMain PA diameter: [X] mm","required":true,"type":"text"},{"id":"s5","label":"Findings - Lungs and Pleura","placeholder":"Pulmonary infarction: [present / absent — location, wedge-shaped opacity if present]\nHampton hump: [present / absent]\nPleural effusion: [absent / right / left / bilateral — size: small/moderate/large]\nAtelectasis / consolidation: [describe]","required":false,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Lower extremity DVT (if pelvic-thigh coverage): [describe]\nOsseous structures and soft tissues...","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Acute / Chronic / No] pulmonary embolism.\n2. [If PE present]: Distribution — [saddle/central/lobar/segmental/subsegmental], [bilateral/right/left].\n3. Right heart strain: [present / absent]. RV/LV ratio: [X].\n4. Associated findings: [pulmonary infarction / pleural effusion / atelectasis].","required":true,"type":"text"}]'::jsonb,
 '[{"id":"c1","trigger_keyword":"pulmonary embolism","add_section":"Pulmonary Arteries","section_content":"PE confirmed. Detail filling defect location (saddle/central/lobar/segmental/subsegmental), laterality, and estimated extent of luminal occlusion."},{"id":"c2","trigger_keyword":"right heart strain","add_section":"Right Heart Strain Assessment","section_content":"Features of right heart strain present: RV/LV ratio, septal deviation, IVC/hepatic vein contrast reflux, PA calibre."}]'::jsonb,
 false, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Coronary Angiography (CTCA)',
 'Comprehensive CTCA report with Agatston calcium scoring and per-vessel stenosis grading',
 'CT Chest',
 '[{"id":"s1","label":"Technique","placeholder":"ECG-gated CT coronary angiography was performed following IV contrast. Heart rate: [X] bpm. Beta-blockade administered: [yes/no]. NTG administered: [yes/no]. Image quality: [excellent/good/adequate/limited due to motion/calcium].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Chest pain / known CAD / pre-operative assessment / dyspnoea...","required":true,"type":"text"},{"id":"s3","label":"Calcium Scoring (Agatston)","placeholder":"Left main: [X]\nLAD: [X]\nLCx: [X]\nRCA: [X]\nTotal Agatston Score: [X]\nPercentile for age/sex: [X]th\nRisk category: [no calcium / minimal / mild / moderate / severe]","required":true,"type":"text"},{"id":"s4","label":"Coronary Anatomy","placeholder":"Dominance: [right dominant / left dominant / co-dominant]","required":true,"type":"text"},{"id":"s5","label":"Left Main Stem","placeholder":"Origin: [normal]\nCourse: [normal, bifurcating into LAD and LCx]\nLumen: [no stenosis / mild <25% / moderate 25-49% / significant ≥50%]\nPlaque: [absent / calcified / non-calcified / mixed]","required":true,"type":"text"},{"id":"s6","label":"LAD and Diagonals","placeholder":"Proximal LAD: [no stenosis]\nMid LAD: [no stenosis]\nDistal LAD: [no stenosis]\nD1: [normal]\nD2: [normal]","required":true,"type":"text"},{"id":"s7","label":"Left Circumflex and OM Branches","placeholder":"Proximal LCx: [no stenosis]\nMid/distal LCx: [no stenosis]\nOM1: [normal]\nOM2: [normal]","required":true,"type":"text"},{"id":"s8","label":"Right Coronary Artery","placeholder":"Proximal RCA: [no stenosis]\nMid RCA: [no stenosis]\nDistal RCA: [no stenosis]\nPDA: [normal]\nPLV branches: [normal]","required":true,"type":"text"},{"id":"s9","label":"Cardiac Structures","placeholder":"LV size and wall thickness: [normal]\nRV: [normal]\nAortic root and ascending aorta: [normal, measuring X mm at sinuses]\nValves: [aortic — no calcification; mitral — normal]\nPericardium: [no effusion, no thickening]","required":true,"type":"text"},{"id":"s10","label":"Incidental Thoracic Findings","placeholder":"Lung parenchyma, pleura, mediastinum, visualised upper abdomen — incidental findings mandatory...","required":true,"type":"text"},{"id":"s11","label":"Impression","placeholder":"1. Agatston calcium score: [X] — [risk category].\n2. [No haemodynamically significant stenosis / Significant stenosis in LAD — describe].\n3. [Other significant findings].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

-- ─────────────────────────────────────────────────────────────
-- CT ABDOMEN/PELVIS
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'CT Abdomen/Pelvis - Normal',
 'Standard normal CT abdomen and pelvis report with full organ-by-organ assessment',
 'CT Abdomen/Pelvis',
 '[{"id":"s1","label":"Technique","placeholder":"Helical CT of the abdomen and pelvis was performed following IV contrast in the portal venous phase, with oral contrast. Axial images reviewed with coronal and sagittal reformats.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings - Liver and Biliary","placeholder":"LIVER: Normal in size and attenuation. Smooth surface contour. No focal hepatic lesion. No intrahepatic biliary dilatation.\nGALLBLADDER: Normal in size. Wall thickness within normal limits. No calculi, polyps, or sludge. No pericholecystic fluid.\nBILIARY TREE: The common bile duct measures within normal limits. No biliary dilatation.","required":true,"type":"text"},{"id":"s4","label":"Findings - Pancreas","placeholder":"The pancreas is normal in size, morphology, and attenuation. No focal pancreatic lesion. No pancreatic ductal dilatation. Peripancreatic fat planes are preserved.","required":true,"type":"text"},{"id":"s5","label":"Findings - Spleen and Adrenals","placeholder":"SPLEEN: Normal in size. No focal splenic lesion.\nADRENAL GLANDS: Both adrenal glands are normal in morphology and size. No adrenal nodule.","required":true,"type":"text"},{"id":"s6","label":"Findings - Kidneys and Ureters","placeholder":"KIDNEYS: Both kidneys enhance symmetrically with normal corticomedullary differentiation. No hydronephrosis, calculus, or focal renal mass. No perinephric collection.\nURETERS: No ureteral dilatation or calculus along the visualised course bilaterally.","required":true,"type":"text"},{"id":"s7","label":"Findings - Bowel","placeholder":"The small bowel is normal in calibre, wall thickness, and enhancement. The colon from caecum to rectum is normal in calibre and haustra. The appendix is visualised and normal. No free air.","required":true,"type":"text"},{"id":"s8","label":"Findings - Pelvis and Retroperitoneum","placeholder":"PELVIS: The urinary bladder has normal wall thickness and contents. [Uterus/Prostate and seminal vesicles]: normal. No pelvic free fluid.\nRETROPERITONEUM: No retroperitoneal or mesenteric lymphadenopathy. The abdominal aorta and iliac vessels are normal in calibre without aneurysm.","required":true,"type":"text"},{"id":"s9","label":"Findings - Other","placeholder":"No free intraperitoneal fluid or gas. Visualised lung bases: clear. Osseous structures: no fracture or suspicious lesion. Psoas muscles: normal bulk and symmetry. No abdominal wall hernia.","required":false,"type":"text"},{"id":"s10","label":"Impression","placeholder":"1. No acute abdominal or pelvic abnormality.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Abdomen/Pelvis - Kidney Stone / Ureteric Colic',
 'Non-contrast CT urogram (stone protocol) with calculus characterisation and hydronephrosis grading',
 'CT Abdomen/Pelvis',
 '[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the abdomen and pelvis was performed using a low-dose stone protocol (axial slice thickness 5 mm, bone kernel). No intravenous or oral contrast administered.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Acute flank pain / haematuria / suspected nephrolithiasis...","required":true,"type":"text"},{"id":"s3","label":"Findings - Right Kidney","placeholder":"Size: [X] cm craniocaudal\nCortical thickness: [normal]\nParenchymal density: [normal]\nCalculus: [present / absent]\n  — Location: [renal pelvis / upper calix / mid calix / lower calix]\n  — Size: [X] mm\n  — Density: [X] HU\n  — Posterior acoustic shadow / stone sign: [present]\nHydronephrosis: [absent / mild / moderate / severe]\nPerinephric fat stranding: [absent / present]","required":true,"type":"text"},{"id":"s4","label":"Findings - Left Kidney","placeholder":"Size: [X] cm craniocaudal\nCortical thickness: [normal]\nParenchymal density: [normal]\nCalculus: [present / absent]\n  — Location: [renal pelvis / upper calix / mid calix / lower calix]\n  — Size: [X] mm\n  — Density: [X] HU\nHydronephrosis: [absent / mild / moderate / severe]\nPerinephric fat stranding: [absent / present]","required":true,"type":"text"},{"id":"s5","label":"Findings - Ureters","placeholder":"RIGHT URETER: [No ureteral calculus / Calculus at proximal / mid / distal / VUJ]\n  — Size: [X] mm, Density: [X] HU\n  — Periureteric fat stranding: [present / absent]\n  — Proximal hydroureter: [present / absent]\nLEFT URETER: [No ureteral calculus / Calculus at ...]\n  — Size: [X] mm\n  — Periureteric fat stranding: [present / absent]","required":true,"type":"text"},{"id":"s6","label":"Findings - Bladder and Other","placeholder":"URINARY BLADDER: Wall thickness normal. No intravesical calculus or filling defect.\nOTHER ABDOMINAL FINDINGS: [Describe incidental findings or state none]\nVISUALISED LUNG BASES: [Clear / Describe any finding]\nOSSEOUS STRUCTURES: [No fracture or suspicious lesion]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Right / Left / Bilateral] renal calculus, measuring [X] mm, [location], density [X] HU.\n2. Ureteric calculus at [location], measuring [X] mm — [obstructing / non-obstructing].\n3. [Mild / Moderate / Severe / No] hydronephrosis on the [right / left].\n4. Periureteric fat stranding consistent with ureteric colic.\n5. Contralateral kidney: [normal / calculus — describe].","required":true,"type":"text"}]'::jsonb,
 '[{"id":"c1","trigger_keyword":"kidney stone","add_section":"Findings - Right Kidney","section_content":"Renal calculus: size (mm), location (pole/pelvis), HU density, associated hydronephrosis grade, perinephric stranding."},{"id":"c2","trigger_keyword":"hydronephrosis","add_section":"Findings - Ureters","section_content":"Hydronephrosis present. Assess ureters for obstructing calculus — location along right or left ureter from PUJ to VUJ."}]'::jsonb,
 false, 0),

-- ─────────────────────────────────────────────────────────────
-- CT HEAD / BRAIN
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'CT Head - Normal',
 'Standard normal non-contrast CT head report',
 'CT Head',
 '[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the head was performed using standard axial acquisitions reviewed on brain, subdural, and bone window settings.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"BRAIN PARENCHYMA: No intracranial haemorrhage. No focal area of abnormal density. The grey-white matter differentiation is preserved. No sulcal or gyral asymmetry.\n\nVENTRICLES AND CSF SPACES: The lateral ventricles, third ventricle, and fourth ventricle are normal in size and configuration. The basal cisterns are patent and symmetric. The sulci and Sylvian fissures are of normal calibre.\n\nMIDLINE: No midline shift. The falx cerebri and tentorium cerebelli are unremarkable.\n\nPOSTERIOR FOSSA: The cerebellar hemispheres and vermis are normal. The brainstem is unremarkable. The fourth ventricle is normal.\n\nCALVARIUM AND SKULL BASE: The calvarium is intact with no cortical defect, fracture line, or suspicious lesion. The skull base is intact. The sella turcica is normal.\n\nPARANASAL SINUSES: The paranasal sinuses are well pneumatised with no significant mucosal thickening or fluid level.\n\nMASTOID AIR CELLS: The mastoid air cells are well aerated bilaterally.\n\nSOFT TISSUES: No scalp haematoma or soft tissue swelling.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute intracranial abnormality.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Head - Acute Stroke / Ischaemia',
 'Non-contrast CT head for acute stroke with ASPECTS scoring and CTA findings',
 'CT Head',
 '[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the head performed urgently. Reviewed on brain, subdural, and bone window settings. [CTA head and neck performed — separate report / included below].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Acute neurological deficit. NIHSS: [X]. Onset: [X hours]. Last known well: [time]. Thrombolysis window: [eligible / not eligible].","required":true,"type":"text"},{"id":"s3","label":"ASPECTS Scoring (if MCA territory)","placeholder":"ASPECTS Score: [X]/10\nRegions scored (1 point each — 0 = abnormal):\nCaudate (C): [normal/abnormal]\nPutamen (P): [normal/abnormal]\nInternal capsule (IC): [normal/abnormal]\nInsular ribbon (I): [normal/abnormal]\nM1 (ant MCA cortex): [normal/abnormal]\nM2 (ant temporal): [normal/abnormal]\nM3 (post temporal): [normal/abnormal]\nM4 (ant MCA superior): [normal/abnormal]\nM5 (lateral MCA superior): [normal/abnormal]\nM6 (post MCA superior): [normal/abnormal]","required":true,"type":"text"},{"id":"s4","label":"Findings - Parenchyma","placeholder":"Early ischaemic changes: [present / absent]\n  — Territory: [MCA / ACA / PCA / posterior fossa / lacunar]\n  — Side: [right / left]\n  — Density change: [subtle / moderate / dense — loss of grey-white differentiation, insular ribbon sign, lenticulostriate obscuration]\nHAEMORRHAGE: [None / Haemorrhagic transformation type I/II / Primary ICH — location, volume estimate]\nHYPERDENSE ARTERY SIGN: [present — vessel: / absent]","required":true,"type":"text"},{"id":"s5","label":"Findings - CTA (if performed)","placeholder":"LARGE VESSEL OCCLUSION (LVO): [present / absent]\n  — Vessel: [ICA / M1 / M2 / basilar artery / PCA / ACA]\n  — Side: [right / left]\n  — Collateral grade: [good / moderate / poor]\nINTRACRANIAL ARTERIES: [No occlusion or significant stenosis beyond that noted above]\nCARVICAL ARTERIES: [ICA and vertebral arteries — stenosis, dissection, atherosclerosis]","required":false,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Ventricles, sulci, skull, sinuses, mastoids, soft tissues...","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Early ischaemic changes / No definite acute infarction] in the [territory] territory — [right / left side]. ASPECTS: [X]/10.\n2. [Haemorrhagic transformation / No haemorrhage].\n3. [LVO: M1 occlusion right MCA / No LVO identified].\n4. Collateral status: [good / moderate / poor].\n5. Recommendation: [Thrombolysis / Thrombectomy / CT perfusion / MRI DWI / Neurology review].","required":true,"type":"text"}]'::jsonb,
 '[{"id":"c1","trigger_keyword":"stroke","add_section":"ASPECTS Scoring (if MCA territory)","section_content":"MCA territory ischaemia — complete ASPECTS scoring mandatory. Score each of the 10 regions (C, P, IC, I, M1–M6). ASPECTS <6 associated with poor outcome with thrombolysis."},{"id":"c2","trigger_keyword":"haemorrhage","add_section":"Findings - Parenchyma","section_content":"Intracranial haemorrhage identified. Classify: intraparenchymal / subarachnoid / subdural / epidural. Location, volume estimate (ABC/2 method), midline shift, ventricular extension, surrounding oedema."},{"id":"c3","trigger_keyword":"LVO","add_section":"Findings - CTA (if performed)","section_content":"Large vessel occlusion identified. Specify vessel (ICA/M1/M2/basilar), laterality, collateral grade. Assess suitability for thrombectomy."}]'::jsonb,
 false, 0),

