-- CT SPINE
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'CT Cervical Spine - Trauma / Assessment',
 'CT cervical spine report for trauma and degenerative assessment',
 'CT Spine',
 '[{"id":"s1","label":"Technique","placeholder":"CT of the cervical spine was performed from the skull base to the C7/T1 junction using helical technique with multiplanar reconstructions in sagittal and coronal planes, reviewed on bone and soft tissue windows.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Trauma / neck pain / suspected fracture / pre-operative assessment...","required":true,"type":"text"},{"id":"s3","label":"Alignment","placeholder":"Cervical alignment: [normal lordosis preserved / loss of lordosis / kyphosis / anterolisthesis / retrolisthesis — level and grade]\nAnterior vertebral line: [intact]\nPosterior vertebral line: [intact]\nSpinolaminar line: [intact]","required":true,"type":"text"},{"id":"s4","label":"Vertebral Bodies and Posterior Elements","placeholder":"C1: [normal ring, dens, atlantoaxial articulation — ADI [X] mm, normal <3 mm adult]\nC2: [dens intact, no fracture, body normal]\nC3–C7: [describe level by level — body height, end-plates, cortex, pedicles, laminae, spinous processes, uncovertebral joints, facet joints]\nFACET JOINTS: [normal / osteoarthropathy — levels]\nUNCOVERTEBRAL JOINTS: [normal / osteophytes — levels]","required":true,"type":"text"},{"id":"s5","label":"Disc Spaces and Foraminal Patency","placeholder":"C2/3 to C7/T1: [disc heights normal / reduced at ... — osteophytes, foraminal compromise — mild/moderate/severe, bilaterally at each level]","required":true,"type":"text"},{"id":"s6","label":"Spinal Canal","placeholder":"Spinal canal dimensions: [adequate at all levels / reduced AP diameter at ... — normal cervical canal ≥13 mm]\nThecal sac: [no significant compression]","required":true,"type":"text"},{"id":"s7","label":"Soft Tissues and Other","placeholder":"PREVERTEBRAL SOFT TISSUES: [normal / swelling — levels]\nVISUALISED LUNG APICES: [clear / describe]\nSKULL BASE AND CRANIOCERVICAL JUNCTION: [normal]","required":false,"type":"text"},{"id":"s8","label":"Impression","placeholder":"1. [No acute fracture or malalignment / Fracture at ... — describe type, displacement, canal compromise].\n2. [Degenerative changes — most significant level(s) and severity of foraminal/canal compromise].\n3. [Other significant findings].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Lumbar Spine - Degenerative / Pain',
 'CT lumbar spine report for degenerative disease, disc disease, and stenosis',
 'CT Spine',
 '[{"id":"s1","label":"Technique","placeholder":"CT of the lumbar spine was performed using helical technique with sagittal and coronal multiplanar reconstructions, reviewed on bone and soft tissue windows.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Low back pain / radiculopathy / suspected disc herniation / pre-operative assessment...","required":true,"type":"text"},{"id":"s3","label":"Alignment and Vertebral Bodies","placeholder":"Lumbar alignment: [normal lordosis / loss of lordosis / scoliosis — Cobb angle]\nVertebral bodies L1–L5 and S1: [normal height and density / compression fractures — level, degree / Modic changes — type, levels / Schmorl nodes — levels]\nPosterior elements: [pedicles, laminae, spinous processes, transverse processes — normal / describe abnormality]\nFacet joints: [normal / facet arthropathy — level and severity — mild/moderate/severe; synovial cysts if present]","required":true,"type":"text"},{"id":"s4","label":"Disc Levels - L1/2 to L5/S1","placeholder":"L1/2: [normal disc height, no herniation, no significant stenosis]\nL2/3: [normal disc height, no herniation, no significant stenosis]\nL3/4: [normal disc height, no herniation, no significant stenosis]\nL4/5: [disc height, disc pathology — bulge/protrusion/extrusion/sequestration, direction, nerve root effect, foraminal stenosis grade, canal AP dimension]\nL5/S1: [disc height, disc pathology, foraminal status, nerve root effect]","required":true,"type":"text"},{"id":"s5","label":"Spinal Canal and Neural Foramina","placeholder":"Central canal (AP dimension at each level — normal lumbar ≥15 mm):\nL1/2: [X] mm\nL2/3: [X] mm\nL3/4: [X] mm\nL4/5: [X] mm — [mild/moderate/severe stenosis]\nL5/S1: [X] mm\n\nNeural foramina: [adequate bilaterally / compromise at — level/side/grade]","required":true,"type":"text"},{"id":"s6","label":"Soft Tissues and Sacroiliac Joints","placeholder":"PARASPINAL MUSCLES: [normal bulk and symmetry / fatty infiltration / atrophy — side]\nSACROILIAC JOINTS: [normal / sclerosis / erosion / widening]\nPSOAS MUSCLES: [normal / asymmetry — side]\nVISUALISED ABDOMEN: [no aneurysm / describe incidental finding]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Degenerative disc disease] — most significant at [level(s)].\n2. [Disc herniation — type, level, side — with/without nerve root compression].\n3. [Central canal stenosis — level, severity].\n4. [Foraminal stenosis — level, side, severity].\n5. [No fracture / Fracture — describe].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Paranasal Sinuses - Normal / Sinusitis',
 'CT PNS report for inflammatory, structural, and pre-operative assessment',
 'CT Head',
 '[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the paranasal sinuses was performed using helical technique reviewed in coronal, axial, and sagittal planes on bone and soft tissue windows.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Chronic sinusitis / pre-FESS assessment / facial pain / nasal obstruction...","required":true,"type":"text"},{"id":"s3","label":"Findings - Sinuses","placeholder":"MAXILLARY SINUSES: [Right: clear / mucosal thickening — [X] mm / fluid level / polyp / complete opacification. Left: clear / describe]\nETHMOID SINUSES: [Anterior: clear / describe. Posterior: clear / describe — bilaterally]\nFRONTAL SINUSES: [Right: clear / describe. Left: clear / describe. Aplastic: Y/N]\nSPHENOID SINUS: [clear / mucosal thickening / fluid level / describe]\nLUNDY-KENNEDY SCORE (if pre-op): [Right: X/12, Left: X/12, Total: X/24]","required":true,"type":"text"},{"id":"s4","label":"Nasal Cavity and Septum","placeholder":"NASAL SEPTUM: [midline / deviated — right/left, level, grade]\nNASAL TURBINATES: [inferior turbinate hypertrophy — right/left; middle turbinate — concha bullosa right/left / pneumatised / paradoxical curvature]\nNASAL POLYPS: [absent / present — location]","required":true,"type":"text"},{"id":"s5","label":"Ostiomeatal Complex","placeholder":"RIGHT OMC: [patent / obstructed — by mucosal disease / polyp / concha bullosa / Haller cell]\nLEFT OMC: [patent / obstructed — describe]","required":true,"type":"text"},{"id":"s6","label":"Anatomical Variants and Key Surgical Landmarks","placeholder":"CRIBRIFORM PLATE: [symmetric, Keros type: I/II/III]\nORBITAL WALLS (LAMINA PAPYRACEA): [intact bilaterally / dehiscence — right/left]\nOPTIC NERVES: [not at risk / describe proximity to sphenoid]\nCAROTID ARTERIES: [not dehiscent into sphenoid / describe if dehiscent]\nHALLER CELLS: [present — right/left / absent]\nONODI CELLS: [present / absent]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Bilateral / Right / Left] chronic rhinosinusitis with [mucosal thickening / polypoid change / complete opacification] of [sinus(es)].\n2. [Obstructed OMC right/left — cause].\n3. [Anatomical variants relevant to surgical planning].\n4. [No acute complication / Orbital / Intracranial extension — describe].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'CT Neck - Soft Tissue / Mass',
 'CT neck with contrast for mass, lymphadenopathy, or abscess',
 'CT Head',
 '[{"id":"s1","label":"Technique","placeholder":"Contrast-enhanced CT of the neck was performed in the portal venous phase from the skull base to the thoracic inlet, reviewed in axial, coronal, and sagittal planes on soft tissue and bone windows.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Neck mass / lymphadenopathy / abscess / primary malignancy staging...","required":true,"type":"text"},{"id":"s3","label":"Findings - Primary Lesion (if applicable)","placeholder":"Location: [describe anatomical space — anterior triangle / posterior triangle / midline / parapharyngeal / retropharyngeal / parotid]\nSize: [X] x [X] x [X] mm\nMorphology: [solid / cystic / heterogeneous / rim-enhancing]\nEnhancement: [avid / moderate / peripheral / none]\nMargins: [well-defined / ill-defined]\nAdjacent structures: [involvement of vessels, airway, vertebral column]","required":false,"type":"text"},{"id":"s4","label":"Lymph Node Assessment","placeholder":"Level I (submental/submandibular): [no abnormal node / enlarged — side, size, morphology]\nLevel II (upper jugular): [right: X mm / left: X mm / describe]\nLevel III (mid jugular): [describe]\nLevel IV (lower jugular): [describe]\nLevel V (posterior triangle): [describe]\nLevel VI (central compartment): [describe]\n\nCharacteristics of abnormal nodes: [necrotic / matted / extranodal extension / calcified]","required":true,"type":"text"},{"id":"s5","label":"Pharynx, Larynx and Airway","placeholder":"Nasopharynx: [normal / describe]\nOropharynx: [normal / describe]\nHypopharynx: [normal / describe]\nLarynx: [epiglottis, arytenoids, vocal cords, subglottis — normal / describe]\nAirway: [patent / compromise at ...]","required":true,"type":"text"},{"id":"s6","label":"Thyroid and Salivary Glands","placeholder":"THYROID: [normal in size and echotexture / nodule — size, location, density]\nPAROTID GLANDS: [normal bilaterally / describe]\nSUBMANDIBULAR GLANDS: [normal bilaterally / describe]","required":false,"type":"text"},{"id":"s7","label":"Vascular Structures","placeholder":"Carotid arteries: [normal bilaterally / encasement / compression / invasion]\nInternal jugular veins: [patent bilaterally / thrombosis — side]\nGreat vessels: [normal]","required":false,"type":"text"},{"id":"s8","label":"Impression","placeholder":"1. [Describe primary finding — mass/node/abscess with location, size, characteristics].\n2. [Lymphadenopathy — levels, laterality, concerning features for malignancy].\n3. [Airway status].\n4. [Recommendations: biopsy / PET-CT / MRI for soft tissue characterisation / ENT review].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

