('00000000-0000-0000-0000-000000000000',
 'MRI Brain - Normal',
 'Standard normal MRI brain with full sequence review',
 'MRI Brain',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the brain was performed on a [1.5T / 3T] system including T1W, T2W, FLAIR, DWI (b=0 and b=1000), T2* GRE, and post-gadolinium T1W sequences in axial, sagittal, and coronal planes.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"DIFFUSION (DWI/ADC): No restricted diffusion to suggest acute infarction.\n\nBRAIN PARENCHYMA: Normal signal intensity throughout the cerebral cortex and subcortical white matter on all sequences. No focal signal abnormality. The grey-white matter junction is well-defined. No cortical or subcortical lesion.\n\nBASAL GANGLIA AND THALAMI: Normal signal bilaterally. No haemorrhage, abnormal signal, or focal lesion.\n\nBRAINSTEM AND CEREBELLUM: The brainstem (midbrain, pons, medulla) is normal in size and signal. The cerebellar hemispheres and vermis are normal. The fourth ventricle is normal.\n\nVENTRICLES AND CSF SPACES: The lateral ventricles are symmetric and normal in size. The third and fourth ventricles are normal. The basal cisterns are patent. The sulci are of normal calibre for age.\n\nMIDLINE STRUCTURES: No midline shift. The corpus callosum is normal in morphology and signal.\n\nPOST-GADOLINIUM: No abnormal parenchymal, meningeal, or vascular enhancement.\n\nMRS / PERFUSION (if performed): [normal / describe]\n\nCALVARIUM AND SKULL BASE: Intact with no focal lesion.\n\nPARANASAL SINUSES: Minimal mucosal thickening in [sinus] — otherwise clear. MASTOID AIR CELLS: Well-aerated bilaterally.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute intracranial abnormality.\n2. Normal MRI of the brain.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000',
 'MRI Brain - Multiple Sclerosis / Demyelination',
 'MRI brain reporting format for MS with McDonald criteria lesion characterisation',
 'MRI Brain',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the brain with and without gadolinium on a [1.5T/3T] system: T1W, T2W, FLAIR, DWI, T2*GRE, post-contrast T1W axial and coronal sequences.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known / suspected multiple sclerosis. Clinical episode: [date, symptoms]. Prior MRI: [date, institution].","required":true,"type":"text"},{"id":"s3","label":"White Matter Lesions - FLAIR/T2","placeholder":"PERIVENTRICULAR: [present — number: X, max size: X mm, ovoid, perpendicular orientation — Dawson fingers: present/absent]\nJUXTACORTICAL / CORTICAL: [present — number: X / absent]\nINFRATENTORIAL:\n  Brainstem: [lesion — location, size / absent]\n  Cerebellum: [lesion / absent]\nSPINAL CORD (if included): [cervical/thoracic cord lesion — level, size / absent]\n\nTotal T2 lesion count: [X]\nTotal T2 lesion volume (approximate): [small / moderate / large burden]","required":true,"type":"text"},{"id":"s4","label":"Enhancing Lesions (Active Disease)","placeholder":"POST-GADOLINIUM: [No enhancing lesion — no evidence of active demyelination]\n[OR: Enhancing lesion(s) identified — number: X, locations: ..., morphology: open-ring/closed-ring/solid, size: X mm]\n\nActive vs. chronic: [ring enhancement / closed ring — open ring more specific for demyelination vs tumour]","required":true,"type":"text"},{"id":"s5","label":"Comparison with Prior MRI","placeholder":"Compared with prior MRI dated [date]:\n[Stable lesion burden / New lesion(s) at ... / Enlarged lesion(s) at ... / New enhancement at ...]\nDissemination in time (DIT): [met / not met / indeterminate]\nDissemination in space (DIS): [met / not met]","required":false,"type":"text"},{"id":"s6","label":"Other Findings","placeholder":"Brain volume: [normal for age / global atrophy — mild/moderate/severe / focal atrophy — describe]\nCorpus callosum: [normal / thinning — body/splenium]\nCortical thinning: [absent / present]\nBlack holes (T1 hypointense chronic lesions): [absent / present — number]\nVentricles and sulci: [normal / prominent — degree]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [X] T2/FLAIR white matter lesions in a distribution consistent with demyelinating disease (periventricular, juxtacortical, infratentorial).\n2. [No active enhancing lesion — no evidence of current disease activity / Enhancing lesion at ... — active demyelination].\n3. Comparison: [stable / new lesions — specify / new enhancement].\n4. McDonald 2017 criteria: DIS [met/not met], DIT [met/not met/indeterminate].\n5. Clinical correlation recommended.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'MRI Brain - Tumour / Mass Lesion',
 'MRI brain for intracranial tumour with full characterisation and differential',
 'MRI Brain',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the brain with and without gadolinium on a [1.5T/3T] system: T1W, T2W, FLAIR, DWI, T2*GRE/SWI, post-contrast T1W (axial, coronal, sagittal). [MRS / perfusion DSC / ASL / tractography if performed].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Suspected intracranial tumour / known malignancy with brain metastases / post-treatment follow-up...","required":true,"type":"text"},{"id":"s3","label":"Primary Lesion Characterisation","placeholder":"LOCATION: [lobe/region — frontal/parietal/temporal/occipital/cerebellum/brainstem/sellar/extra-axial]\nLATERALITY: [right / left / midline]\nSIZE: [X] x [X] x [X] mm\nSIGNAL:\n  T1: [isointense / hypointense / heterogeneous / haemorrhage]\n  T2/FLAIR: [hyperintense / mixed]\n  DWI: [restricted / facilitated]\n  SWI/GRE: [haemorrhage / calcification / susceptibility]\nENHANCEMENT: [avid / ring / heterogeneous / none / leptomeningeal]\nMARGINS: [well-defined / infiltrative]\nPERITUMOURAL OEDEMA: [absent / vasogenic — mild/moderate/severe — extent]\nNECROSIS: [present / absent]","required":true,"type":"text"},{"id":"s4","label":"Mass Effect and Herniation","placeholder":"MIDLINE SHIFT: [absent / present — [X] mm to the [right/left]]\nVENTRICULAR COMPRESSION: [absent / present — lateral ventricle / third ventricle compressed]\nHERNIATION: [absent / subfalcine / uncal / tonsillar — describe degree]\nHYDROCEPHALUS: [absent / communicating / obstructive]","required":true,"type":"text"},{"id":"s5","label":"Additional Lesions (Metastases)","placeholder":"[Single lesion / Multiple lesions — number: X]\nAdditional lesions: [describe location and size of each, or state: dominant lesion only, satellite lesions absent]\nLeptomeningeal disease: [absent / present — describe]","required":false,"type":"text"},{"id":"s6","label":"MRS / Perfusion (if performed)","placeholder":"MR SPECTROSCOPY: [Cho:Cr ratio: X — elevated/normal. NAA: reduced/normal. Lipid/lactate: present/absent]\nPERFUSION (rCBV): [elevated — high grade / normal/low — low grade]\nDWI ADC: [X x10⁻³ mm²/s]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [X] x [X] x [X] mm [intra-axial / extra-axial] lesion in the [location], with [enhancement pattern], [oedema], [mass effect] — most likely represents [differential: primary glioma WHO grade / metastasis / meningioma / lymphoma / abscess].\n2. [Midline shift / herniation if present].\n3. [Multiple lesions — metastatic pattern].\n4. Recommendation: [neurosurgical review / MR spectroscopy / stereotactic biopsy / systemic staging / DWI for abscess].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

