 'MRI Musculoskeletal',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the [right/left] knee was performed on a [1.5T/3T] system including PD fat-sat, T2W fat-sat, T1W, and STIR sequences in axial, sagittal, and coronal planes.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Knee pain / suspected meniscal tear / ligament injury / cartilage assessment / post-trauma...","required":true,"type":"text"},{"id":"s3","label":"Menisci","placeholder":"MEDIAL MENISCUS:\n  Body: [normal / grade I / grade II / grade III horizontal / radial / bucket-handle tear — apex/body/posterior horn]\n  Posterior horn: [normal / tear — describe]\n  Anterior horn: [normal]\n\nLATERAL MENISCUS:\n  Body: [normal / tear — describe]\n  Posterior horn: [normal / tear — describe including root tear]\n  Anterior horn: [normal]\n\nDiscoid meniscus: [absent / present — complete/incomplete — right/left lateral]","required":true,"type":"text"},{"id":"s4","label":"Ligaments","placeholder":"ACL: [intact — normal signal and course / partial / complete tear — fibres at femoral/tibial attachment / mid-substance]\nPCL: [intact / partial / complete tear]\nMCL: [intact / sprain grade I/II/III — superficial/deep fibres]\nLCL: [intact / sprain — grade]\nPOSTEROLATERAL CORNER (PLC): [intact / injury — popliteus/popliteofibular ligament/biceps femoris]","required":true,"type":"text"},{"id":"s5","label":"Articular Cartilage","placeholder":"MEDIAL COMPARTMENT:\n  Medial femoral condyle: [normal / focal chondral defect — ICRS grade 1-4, size]\n  Medial tibial plateau: [normal / describe]\nLATERAL COMPARTMENT:\n  Lateral femoral condyle: [normal / describe]\n  Lateral tibial plateau: [normal / describe]\nPATELLOFEMORAL COMPARTMENT:\n  Patella: [normal / thinning / focal defect — ICRS grade]\n  Trochlea: [normal / trochlear dysplasia — Dejour type]","required":true,"type":"text"},{"id":"s6","label":"Bone Marrow and Other Structures","placeholder":"BONE MARROW OEDEMA:\n  Medial femoral condyle: [absent / present — grade, size]\n  Lateral femoral condyle: [absent / present]\n  Medial tibial plateau: [absent / present]\n  Lateral tibial plateau: [absent / present]\n  Patella: [absent / present]\n\nJOINT EFFUSION: [absent / small / moderate / large — signal: simple/complex]\nBAKER CYST: [absent / present — size [X] x [X] mm; ruptured / intact]\nHoffa fat pad: [normal / impingement / oedema]\nPlica: [absent / medial plica — thickened]\nPOPLITEAL FOSSA: [no mass]","required":true,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Medial meniscus posterior horn — grade III tear / intact].\n2. [Lateral meniscus — intact / root tear].\n3. [ACL — intact / complete tear].\n4. [MCL — intact / grade II sprain].\n5. [Cartilage — focal chondral defect medial femoral condyle ICRS grade X].\n6. [Bone marrow oedema — medial tibial plateau — contusion pattern].\n7. [Joint effusion — small/moderate/large].","required":true,"type":"text"}]'::jsonb,
