('00000000-0000-0000-0000-000000000000',
 'MRI Shoulder - Rotator Cuff / Labrum',
 'MRI shoulder report covering rotator cuff, labrum, biceps, and AC joint',
 'MRI Musculoskeletal',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the [right/left] shoulder was performed on a [1.5T/3T] system including PD fat-sat, T2W fat-sat, T1W, and STIR sequences in axial, sagittal oblique, and coronal oblique planes. [MR arthrography with intra-articular gadolinium if performed].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Shoulder pain / suspected rotator cuff tear / instability / post-trauma...","required":true,"type":"text"},{"id":"s3","label":"Rotator Cuff","placeholder":"SUPRASPINATUS:\n  Integrity: [intact / partial-thickness tear — articular/bursal/interstitial; surface: X%; size: X mm / full-thickness tear — width: X mm; retraction: none/mild to musculotendinous junction/moderate/severe with retraction to X cm]\n  Fatty atrophy: [none / grade 1-4 — Goutallier]\n\nINFRASPINATUS: [intact / partial / full-thickness tear — describe]\nSUBSCAPULARIS: [intact / partial / full-thickness tear — describe; medial biceps subluxation: present/absent]\nTERES MINOR: [intact / atrophy / describe]","required":true,"type":"text"},{"id":"s4","label":"Biceps Tendon and Labrum","placeholder":"LONG HEAD BICEPS (LHB):\n  Groove: [normal position / subluxed / dislocated]\n  Tendon: [intact / tendinopathy / partial / complete tear]\n  Intra-articular portion: [normal]\n\nGLENOID LABRUM:\n  Anterior: [intact / SLAP I/II/III/IV / Bankart / ALPSA]\n  Posterior: [intact / tear — describe]\n  Superior: [intact / SLAP lesion — grade I/II/III/IV]\n  Inferior: [intact]","required":true,"type":"text"},{"id":"s5","label":"Joint and Bursae","placeholder":"GLENOHUMERAL JOINT EFFUSION: [absent / small / moderate — simple/complex]\nSUBACROMIAL-SUBDELTOID BURSA: [no fluid / bursitis — mild/moderate/severe; communication with joint]\nACROMIOCLAVICULAR JOINT: [normal / osteoarthropathy / AC separation grade X / osteophytes — inferior impingement]\nACROMION: [type I flat / II curved / III hooked — Bigliani]. Subacromial space: [adequate / narrowed — X mm]","required":true,"type":"text"},{"id":"s6","label":"Bone and Other","placeholder":"HUMERAL HEAD:\n  Marrow signal: [normal / Hill-Sachs defect — size / avascular necrosis — Ficat grade]\n  Articular cartilage: [normal / thinning / focal defect]\nGLENOID:\n  Bony Bankart: [absent / present — size of defect]\n  Cartilage: [normal]\nACROMIOCLAVICULAR JOINT: [as above]\nSUPRASPINATUS FOSSA / SPINOGLENOID NOTCH: [no cyst / paralabral cyst — size, nerve compression]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Supraspinatus: intact / partial-thickness tear articular surface X% / full-thickness tear width X mm, retraction to ...].\n2. [Infraspinatus/Subscapularis — describe].\n3. [LHB — intact / tear / subluxed].\n4. [Labrum — intact / Bankart / SLAP II].\n5. [AC joint — normal / osteoarthropathy with inferior impingement].\n6. [Subacromial bursitis — present/absent].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'MRI Ankle - Tendons / Ligaments',
 'MRI ankle report covering tendons, ligaments, bone marrow, and cartilage',
 'MRI Musculoskeletal',
 '[{"id":"s1","label":"Technique","placeholder":"MRI of the [right/left] ankle was performed on a [1.5T/3T] system including PD fat-sat, T2W fat-sat, T1W, and STIR sequences in axial, sagittal, and coronal planes.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Ankle pain / suspected tendon tear / ligament injury / post-trauma / Achilles tendon assessment...","required":true,"type":"text"},{"id":"s3","label":"Tendons","placeholder":"ACHILLES TENDON:\n  Signal: [normal low signal / tendinopathy — fusiform thickening at X cm from calcaneal insertion / partial tear / complete tear — gap: X mm, retraction: X cm]\n  Peritendinitis: [absent / present]\n  Retrocalcaneal bursa: [normal / bursitis]\n\nPERONEALS:\n  Peroneus brevis: [intact / longitudinal split tear / complete tear; tendon position in groove: normal/subluxed]\n  Peroneus longus: [intact / tear]\n  Superior peroneal retinaculum: [intact / torn]\n\nPOSTERIOR TIBIALIS: [intact / tendinopathy / partial / complete tear — Johnson-Strom grade]\nFLEXOR DIGITORUM LONGUS: [intact / describe]\nFLEXOR HALLUCIS LONGUS: [intact / describe — os trigonum association]\n\nEXTENSOR TENDONS: [intact / describe]","required":true,"type":"text"},{"id":"s4","label":"Ligaments","placeholder":"LATERAL LIGAMENT COMPLEX:\n  ATFL: [intact / partial / complete tear]\n  CFL: [intact / partial / complete tear]\n  PTFL: [intact / tear]\n\nMEDIAL (DELTOID) LIGAMENT: [intact / sprain — superficial/deep fibres]\n\nSYNDESMOSIS:\n  AITFL: [intact / tear]\n  PITFL: [intact / tear]\n  Tibiofibular clear space: [normal / widened]","required":true,"type":"text"},{"id":"s5","label":"Bone Marrow and Joints","placeholder":"BONE MARROW OEDEMA:\n  Talus: [absent / present — region, size]\n  Calcaneum: [absent / present]\n  Distal tibia: [absent / present]\n  Medial/lateral malleolus: [absent / present]\n\nFRACTURE: [absent / stress fracture / osteochondral lesion of talus (OLT) — ICRS grade, location, size, stability]\n\nANKLE JOINT EFFUSION: [absent / small / moderate / large]\nSUBTALAR JOINT: [normal / osteoarthropathy / effusion]\nOS TRIGONUM: [absent / present — signal, FHL impingement]","required":true,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. [Achilles tendon — intact / tendinopathy / partial/complete tear].\n2. [Lateral ligament complex — ATFL tear / intact].\n3. [Peroneal tendons — intact / peroneus brevis split tear].\n4. [OLT — location, grade, size].\n5. [Bone marrow oedema — talus/calcaneum].\n6. [Joint effusion].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
