 'X-Ray Chest',
 '[{"id":"s1","label":"Technique","placeholder":"PA [and lateral] views of the chest.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Fever / productive cough / suspected pneumonia / sepsis...","required":true,"type":"text"},{"id":"s3","label":"Findings - Consolidation","placeholder":"LOCATION: [right/left lobe — upper/middle/lower; segment if identifiable]\nEXTENT: [segmental / lobar / multilobar / bilateral]\nMORPHOLOGY: [homogeneous / heterogeneous; air bronchograms: present/absent; silhouette sign: right heart border / left heart border / diaphragm]\nDENSITY: [dense / hazy / patchy]\nCOMPARED TO PRIOR: [new / unchanged / worsening / improving]","required":true,"type":"text"},{"id":"s4","label":"Findings - Other","placeholder":"PLEURAL EFFUSION: [absent / right / left / bilateral — size: small/moderate/large]\nPNEUMOTHORAX: [absent / present]\nCARDIAC SILHOUETTE: [normal / enlarged]\nOPPOSITE LUNG: [clear / abnormality]\nOSSEOUS AND SOFT TISSUES: [normal / describe]","required":false,"type":"text"},{"id":"s5","label":"Impression","placeholder":"1. [Right/Left/Bilateral] [lobar/segmental/patchy] consolidation, most likely representing [pneumonia / aspiration / pulmonary infarction].\n2. [Pleural effusion if present].\n3. Recommendation: [follow-up CXR in X weeks / CT chest if no resolution / urgent review if haemodynamically unstable].","required":true,"type":"text"}]'::jsonb,
