-- PET-CT
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'PET-CT - Oncology Staging / Restaging',
 'FDG PET-CT report for oncology staging with Deauville/PERCIST assessment',
 'PET-CT',
 '[{"id":"s1","label":"Technique","placeholder":"18F-FDG PET-CT was performed from skull base to mid-thigh. FDG dose: [X] MBq. Blood glucose at time of injection: [X] mmol/L (normal <8 mmol/L). Uptake time: 60 minutes. CT performed with IV contrast (portal venous phase) for combined PET-CT interpretation. Corrected for attenuation, scatter, and random coincidences.","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known [malignancy type] — staging / restaging / response assessment / post-treatment surveillance. Prior PET-CT dated [date] for comparison.","required":true,"type":"text"},{"id":"s3","label":"Findings - Primary Site","placeholder":"PRIMARY TUMOUR:\n  Location: [describe anatomical site]\n  FDG avidity: [present / absent]\n  SUVmax: [X]\n  Size on CT: [X] x [X] mm\n  Local extent: [organ-confined / local invasion — describe structures involved]","required":true,"type":"text"},{"id":"s4","label":"Findings - Regional Lymph Nodes","placeholder":"REGIONAL LYMPH NODES:\n  [Node station — level, side]: [FDG avid — SUVmax [X], short axis [X] mm / non-avid, non-enlarged]\n  [Additional stations as relevant]\n  N-stage assessment: [N0 / N1 / N2 / N3]","required":true,"type":"text"},{"id":"s5","label":"Findings - Distant Metastases","placeholder":"LUNGS: [no FDG-avid nodule / pulmonary metastasis — number, size, SUVmax]\nLIVER: [no FDG-avid lesion / hepatic metastasis — number, size, SUVmax, distribution]\nBONES: [no focal abnormal FDG uptake / osseous metastasis — sites, SUVmax; corresponding CT: lytic/sclerotic/normal density]\nADRENAL GLANDS: [no FDG uptake / avid lesion — right/left, size, SUVmax]\nBRAIN: [not imaged / no FDG-avid metastasis]\nPERITONEUM / OMENTUM: [no FDG uptake / peritoneal deposits]\nOTHER SITES: [describe]","required":true,"type":"text"},{"id":"s6","label":"Incidental Findings","placeholder":"INCIDENTAL FDG UPTAKE:\n  Bowel: [physiological / focal colonic uptake — site — correlate with colonoscopy]\n  Thyroid: [no focal uptake / focal uptake — right/left lobe — correlate with ultrasound]\n  Breast: [no uptake]\n  Other: [describe]\n\nCT INCIDENTAL FINDINGS: [describe any significant CT finding not related to primary pathology]","required":false,"type":"text"},{"id":"s7","label":"Response Assessment (if restaging)","placeholder":"COMPARISON WITH PRIOR PET-CT dated [date]:\n\nDEAUVILLE SCORE (lymphoma): [1/2/3/4/5]\nPERCIST (solid tumours): [CMR / PMR / SD / PMD]\n\nSUMMARY:\n  Primary site: [decreased / stable / increased / resolved FDG activity]\n  Nodes: [decreased / stable / increased / resolved]\n  Distant disease: [decreased / stable / new sites]","required":false,"type":"text"},{"id":"s8","label":"Impression","placeholder":"1. [Staging / Restaging] FDG PET-CT for [malignancy type].\n2. Primary site: [FDG-avid primary tumour — location, SUVmax, size].\n3. Regional nodal disease: [N-stage — avid nodes at ...].\n4. Distant metastases: [M0 — no distant metastasis / M1 — sites: liver, lungs, bones, etc.].\n5. Overall staging: [TNM Stage — cT_ N_ M_].\n6. [Response assessment if applicable: Deauville X / PERCIST — describe].\n7. [Significant incidental finding — recommendation].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

-- ─────────────────────────────────────────────────────────────
-- MAMMOGRAPHY
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'Mammography - Screening / Normal',
 'Standard bilateral digital mammography with BI-RADS classification',
 'Mammography',
 '[{"id":"s1","label":"Technique","placeholder":"Bilateral digital screening mammography — CC and MLO views. [Tomosynthesis (DBT) performed: Y/N]. [Prior mammograms dated [date] available for comparison].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Routine screening mammography. Age: [X]. Relevant history: [family history of breast cancer / BRCA / prior biopsy — describe].","required":true,"type":"text"},{"id":"s3","label":"Breast Composition","placeholder":"ACR BREAST COMPOSITION: [a) Almost entirely fatty / b) Scattered areas of fibroglandular density / c) Heterogeneously dense — may obscure small masses / d) Extremely dense — lowers sensitivity]","required":true,"type":"text"},{"id":"s4","label":"Findings - Right Breast","placeholder":"MASSES: [No mass / Mass — location: clock position, depth; shape: oval/round/irregular; margins: circumscribed/obscured/microlobulated/angular/spiculated; density: low/equal/high/fat-containing; size: [X] mm]\nCALCIFICATIONS: [No suspicious calcification / Calcification — morphology: amorphous/coarse heterogeneous/fine pleomorphic/fine linear/branching; distribution: diffuse/regional/grouped/linear/segmental]\nARCHITECTURAL DISTORTION: [absent / present — location]\nASYMMETRY: [absent / focal/global/developing asymmetry — location]","required":true,"type":"text"},{"id":"s5","label":"Findings - Left Breast","placeholder":"MASSES: [No mass / describe as right breast template above]\nCALCIFICATIONS: [No suspicious calcification / describe]\nARCHITECTURAL DISTORTION: [absent / present]\nASYMMETRY: [absent / present]","required":true,"type":"text"},{"id":"s6","label":"BI-RADS Assessment","placeholder":"ACR BI-RADS CATEGORY:\n[0 — Incomplete / 1 — Negative / 2 — Benign / 3 — Probably benign / 4A — Low suspicion / 4B — Moderate suspicion / 4C — High suspicion / 5 — Highly suggestive of malignancy / 6 — Known biopsy-proven malignancy]\n\nRATIONALE: [state basis for assigned category]","required":true,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. BI-RADS [X] — [category description].\n2. [Recommendation: Routine annual screening / Short-interval follow-up in 6 months / Tissue sampling — core biopsy / Additional imaging — diagnostic mammogram / ultrasound].\n3. [Comparison: no significant change / new finding since prior dated ...].\n4. [Significant incidental finding if any].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000',
 'Mammography - Diagnostic / Suspicious Mass',
 'Diagnostic mammography report for suspicious or symptomatic breast finding',
 'Mammography',
 '[{"id":"s1","label":"Technique","placeholder":"Diagnostic bilateral mammography — CC, MLO, and additional targeted views (spot compression / magnification) of the [right/left] breast at [location]. [Ultrasound performed — separate/included below].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Palpable lump [right/left breast, clock position] / mammographic recall for [finding] / nipple discharge / [other symptom].","required":true,"type":"text"},{"id":"s3","label":"Breast Composition","placeholder":"ACR BREAST COMPOSITION: [a/b/c/d — as per screening report format]","required":true,"type":"text"},{"id":"s4","label":"Findings - Dominant Lesion","placeholder":"LOCATION: [right/left breast, clock position: X o''clock, depth: anterior/middle/posterior third, distance from nipple: X cm; quadrant: UOQ/UIQ/LOQ/LIQ]\nSIZE: [X] x [X] mm\nSHAPE: [oval / round / irregular]\nMARGINS: [circumscribed / obscured / microlobulated / angular / spiculated]\nDENSITY: [low / equal / high / fat-containing]\nASSOCIATED FEATURES: [skin thickening / nipple retraction / trabecular distortion / axillary lymphadenopathy]\nCALCIFICATIONS IN LESION: [absent / present — morphology]\nCOMPARISON: [new / stable / increased in size from prior dated ...]","required":true,"type":"text"},{"id":"s5","label":"Remainder of Breast and Contralateral","placeholder":"REMAINDER OF RIGHT BREAST: [no additional suspicious finding]\nLEFT BREAST: [no suspicious mass, calcification, or architectural distortion / describe]\nAXILLAE: [no lymphadenopathy bilaterally / suspicious node — side, size, morphology]","required":true,"type":"text"},{"id":"s6","label":"BI-RADS Assessment","placeholder":"ACR BI-RADS: [4A / 4B / 4C / 5]\nRATIONALE: [state features driving suspicion level — shape, margins, associated features]","required":true,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. BI-RADS [X] — [suspicious / highly suspicious] lesion in the [right/left] breast, [location], measuring [X] mm.\n2. Recommendation: [Ultrasound-guided core needle biopsy / Stereotactic biopsy for calcifications / Surgical excision].\n3. [Axillary lymphadenopathy — ultrasound-guided FNA if clinically indicated].\n4. Clinical correlation and multidisciplinary breast team review recommended.","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

-- ─────────────────────────────────────────────────────────────
-- NUCLEAR MEDICINE
-- ─────────────────────────────────────────────────────────────
('00000000-0000-0000-0000-000000000000',
 'Nuclear Medicine - Bone Scan (Tc-99m MDP)',
 'Whole body bone scintigraphy report for metastatic and benign bone disease',
 'General',
 '[{"id":"s1","label":"Technique","placeholder":"Whole body bone scintigraphy was performed 3 hours following IV injection of [X] MBq Tc-99m methylenediphosphonate (MDP). Anterior and posterior whole body planar images were acquired. [SPECT/CT of [region] performed additionally].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known [malignancy type] — bone metastasis screening / staging / restaging / bone pain / suspected stress fracture / Paget disease...","required":true,"type":"text"},{"id":"s3","label":"Findings - Skeleton Overview","placeholder":"OVERALL PATTERN: [normal homogeneous skeletal uptake / focal abnormal uptake — single / multiple sites / superscan: diffusely increased uptake with absent renal activity — extensive metastatic disease]\n\nSKULL AND FACE: [no focal abnormal uptake / describe]\nMANDIBLE AND RIBS: [no focal uptake / describe — rib fractures vs. metastases: linear uptake in rib series = fracture; solitary intense focal = metastasis]\nSTERNUM AND CLAVICLES: [normal / describe]\nSPINE (cervical/thoracic/lumbar/sacrum): [no focal uptake / abnormal uptake at — level, laterality, intensity: mild/moderate/intense]\nPELVIS: [normal sacroiliac joints and iliac wings / describe focal uptake]\nLONG BONES (femora, tibiae): [normal / describe]\nHANDS AND FEET: [normal / describe]","required":true,"type":"text"},{"id":"s4","label":"Distinguishing Features","placeholder":"METASTATIC PATTERN FEATURES (if applicable): [multiple foci / axial skeleton predominance / randomly distributed / superscan]\nBENIGN FEATURES: [linear rib uptake consistent with fracture / degenerative joints — symmetric uptake in large joints / metabolic bone disease — diffuse]\nINDETERMINATE FOCI: [describe — correlate with CT/MRI for further characterisation]","required":false,"type":"text"},{"id":"s5","label":"Renal and Soft Tissues","placeholder":"KIDNEYS: [visualised and symmetric — normal tracer excretion / asymmetric — right/left reduced uptake]\nBLADDER: [normal tracer activity]\nSOFT TISSUE UPTAKE: [absent / heterotopic ossification — location / calcification — location]\nINCIDENTAL FINDINGS: [describe]","required":false,"type":"text"},{"id":"s6","label":"Comparison with Prior","placeholder":"Compared with prior bone scan dated [date]:\n[Stable / New lesion(s) at ... / Progression — number/intensity increased / Response — decreased uptake / Flare phenomenon — worsening uptake after initiation of treatment, may represent response]","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [No bone metastasis identified — normal bone scan / Multiple foci of abnormal uptake — pattern consistent with bone metastases — sites: spine (T6, L3), pelvis, ribs / Single focus at ... — indeterminate; CT/MRI correlation recommended].\n2. [Comparison: stable / new lesions / flare phenomenon].\n3. [Incidental finding: rib fractures at ribs X–X / degenerative joint disease — joints].\n4. [SPECT/CT correlation findings if performed].\n5. [Recommendation: correlative MRI for indeterminate lesions / clinical correlation / follow-up bone scan in X months].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000',
 'Nuclear Medicine - HIDA Hepatobiliary Scan',
 'Hepatobiliary scintigraphy (HIDA scan) for biliary dyskinesia and cholecystitis',
 'General',
 '[{"id":"s1","label":"Technique","placeholder":"Hepatobiliary scintigraphy was performed following IV injection of [X] MBq Tc-99m HIDA (mebrofenin/disofenin). Dynamic 60-minute hepatobiliary phase acquired in anterior projection. CCK (sincalide) infusion [performed: dose and rate] for gallbladder ejection fraction assessment. 4-hour delayed images [acquired if indicated].","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Right upper quadrant pain / suspected biliary dyskinesia / acute cholecystitis / post-cholecystectomy pain / biliary leak assessment...","required":true,"type":"text"},{"id":"s3","label":"Hepatic Uptake and Transit","placeholder":"HEPATIC UPTAKE: [prompt and uniform — normal / decreased — hepatic dysfunction]\nPEAK HEPATIC ACTIVITY: [X] minutes (normal <10 minutes)\nINITIAL BILE DUCT ACTIVITY: [seen at [X] minutes]\nSMALL BOWEL TRANSIT: [seen at [X] minutes (normal <60 minutes) / absent at 60 minutes — biliary obstruction or cholecystitis]","required":true,"type":"text"},{"id":"s4","label":"Gallbladder Visualisation","placeholder":"GALLBLADDER VISUALISATION:\n  [Visualised at [X] minutes / Not visualised by 60 minutes — cystic duct obstruction (acute cholecystitis if clinical correlation present) / Not visualised — morphine augmentation performed]\n\nGALLBLADDER EJECTION FRACTION (GBEF):\n  Pre-CCK activity: [X] counts\n  Post-CCK (at 30 min) activity: [X] counts\n  GBEF: [X]% (normal ≥35–40%)\n  REPRODUCTION OF SYMPTOMS with CCK: [yes / no]\n  PAIN SCORE: [X/10 pre vs. X/10 post CCK]","required":true,"type":"text"},{"id":"s5","label":"Biliary Ductal System","placeholder":"COMMON BILE DUCT: [normal calibre and transit / dilated — [X] mm; transit delayed]\nBILIARY LEAK: [absent / present — site: [describe anastomosis/cystic duct/duct of Luschka]; extent: local/free peritoneal]\nRIMSIGN: [absent / present — increased pericholecystic hepatic activity — high specificity for acute cholecystitis]","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. [Normal hepatobiliary scintigraphy — prompt hepatic uptake, gallbladder visualisation at [X] minutes, small bowel transit at [X] minutes, GBEF [X]% — normal].\n[OR: Gallbladder not visualised at 60 minutes with clinical acute RUQ pain — findings consistent with acute cholecystitis].\n[OR: GBEF [X]% (below normal threshold of 35%) with reproduction of symptoms — consistent with biliary dyskinesia / chronic acalculous cholecystitis].\n2. [Biliary leak — site, volume].\n3. Recommendation: [surgical consultation for acute cholecystitis / laparoscopic cholecystectomy for biliary dyskinesia / correlation with ultrasound / follow-up imaging].","required":true,"type":"text"}]'::jsonb,
 '[]'::jsonb, false, 0)

ON CONFLICT DO NOTHING;

-- ============================================================
-- SYSTEM MACROS (25)
