INSERT INTO macros (user_id, trigger, expansion, category, description, usage_count) VALUES

-- ULTRASOUND MACROS
('00000000-0000-0000-0000-000000000000',
 '/us-normal-abd',
 'The liver is normal in size and echotexture without focal lesion. No intrahepatic biliary dilatation. Portal vein is patent with normal hepatopetal flow. The gallbladder is normal with no gallstones or wall thickening. The common bile duct is not dilated. The pancreas is normal in echotexture without focal lesion or ductal dilatation. The spleen is normal in size. Both kidneys are normal in size and echogenicity with maintained corticomedullary differentiation and no hydronephrosis or calculus. The abdominal aorta is normal in calibre. No free intraperitoneal fluid.',
 'abdomen', 'Normal abdominal ultrasound — complete macro', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-normal-kidney',
 'Both kidneys are normal in size with maintained cortical thickness and echogenicity. Corticomedullary differentiation is preserved bilaterally. No hydronephrosis, calculus, or focal mass lesion identified. The collecting systems are not dilated.',
 'abdomen', 'Normal kidneys — bilateral', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-gallstones',
 'Multiple echogenic foci within the gallbladder lumen demonstrating posterior acoustic shadowing consistent with cholelithiasis. The gallbladder wall thickness is within normal limits (less than 3 mm). No pericholecystic fluid. No sonographic Murphy sign elicited. No biliary dilatation.',
 'abdomen', 'Cholelithiasis — no cholecystitis', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-kidney-stone',
 'An echogenic focus with posterior acoustic shadowing is identified within the [right/left] kidney, measuring [X] mm, consistent with a renal calculus. [No/Mild/Moderate/Severe] hydronephrosis is noted on the [right/left]. Perinephric fat stranding: [absent/present].',
 'abdomen', 'Renal calculus finding — fill in size/side/hydronephrosis', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-normal-thyroid',
 'The thyroid gland is normal in size and homogeneous echotexture. The right lobe, left lobe, and isthmus are normal in calibre. No focal nodule, cyst, or calcification. Normal colour Doppler vascularity. No significant cervical lymphadenopathy.',
 'general', 'Normal thyroid ultrasound', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-normal-pelvis',
 'The uterus is normal in size, position, and echotexture. The endometrial thickness is within normal limits for cycle phase. Both ovaries are normal in size and morphology with normal follicular pattern. No adnexal mass or complex cyst. No free fluid in the pouch of Douglas.',
 'general', 'Normal female pelvic ultrasound', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-normal-scrotal',
 'Both testes are normal in size and demonstrate homogeneous echotexture. Normal symmetric colour Doppler flow bilaterally. Both epididymes are normal in size and echogenicity. No hydrocele, varicocele, or focal intratesticular lesion.',
 'general', 'Normal scrotal ultrasound — bilateral', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-carotid-normal',
 'Both common carotid arteries, carotid bifurcations, internal carotid arteries, and external carotid arteries are patent with normal spectral Doppler waveforms. No haemodynamically significant stenosis bilaterally. Intima-media thickness within normal limits bilaterally. No atheromatous plaque. Both vertebral arteries demonstrate normal antegrade flow.',
 'vascular', 'Normal carotid duplex Doppler', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-dvt-negative',
 'The common femoral vein, femoral vein, and popliteal vein are fully compressible bilaterally with no intraluminal echogenic material. Normal phasic Doppler waveforms with augmentation bilaterally. No evidence of deep vein thrombosis in either lower limb.',
 'vascular', 'Negative DVT study — bilateral', 0),

('00000000-0000-0000-0000-000000000000',
 '/us-normal-breast',
 'No focal solid mass, complex cyst, or suspicious architectural distortion identified. The fibroglandular tissue appears normal in echotexture. No skin thickening or nipple retraction. No axillary lymphadenopathy.',
 'general', 'Normal breast ultrasound', 0),

-- CT MACROS
('00000000-0000-0000-0000-000000000000',
 '/ct-normal-chest',
 'The trachea is central with normal calibre. The lungs are clear bilaterally without focal consolidation, ground-glass opacity, pleural effusion, or pneumothorax. No pulmonary nodule or mass. The mediastinal and hilar contours are unremarkable. No pathological lymphadenopathy. The cardiac silhouette is within normal limits. The aorta is normal in calibre. The ribs, sternum, and thoracic spine are intact. Visualised upper abdominal organs are unremarkable.',
 'chest', 'Normal CT chest — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/ct-normal-abd',
 'The liver is normal in size and attenuation without focal lesion. No intrahepatic or extrahepatic biliary dilatation. The common bile duct is not dilated. The gallbladder is normal. The pancreas is normal without focal lesion or ductal dilatation. The spleen is normal in size. Both adrenal glands are normal. Both kidneys enhance symmetrically without focal lesion, hydronephrosis, or calculus. No retroperitoneal or mesenteric lymphadenopathy. The abdominal aorta and iliac vessels are normal in calibre. The bowel is normal in calibre and enhancement. The appendix is visualised and normal. No free intraperitoneal fluid or free gas. Osseous structures are intact.',
 'abdomen', 'Normal CT abdomen/pelvis — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/ct-normal-brain',
 'No intracranial haemorrhage, focal abnormal density, or acute territorial infarction. The grey-white matter differentiation is preserved throughout. The ventricles and sulci are normal in size and configuration for age. The basal cisterns are patent and symmetric. No midline shift or mass effect. The calvarium is intact. The paranasal sinuses and mastoid air cells are well aerated. No skull base abnormality.',
 'neuro', 'Normal CT head — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/ct-normal-cspine',
 'Normal cervical alignment with preservation of lordosis. Vertebral bodies C1 to C7 are normal in height and density. No fracture. The disc spaces are maintained at all levels without significant disc herniation. The spinal canal is adequate at all levels. The neural foramina are patent bilaterally. The prevertebral soft tissues are normal. Visualised lung apices are clear.',
 'spine', 'Normal CT cervical spine', 0),

('00000000-0000-0000-0000-000000000000',
 '/ct-normal-lspine',
 'Normal lumbar alignment with preservation of lordosis. Vertebral bodies L1 to L5 and S1 are normal in height and density. No fracture. The intervertebral disc spaces are maintained at all levels. No significant disc herniation or central canal stenosis. Neural foramina are patent bilaterally at all levels. The sacroiliac joints are normal. Paraspinal muscles are normal.',
 'spine', 'Normal CT lumbar spine', 0),

-- MRI MACROS
('00000000-0000-0000-0000-000000000000',
 '/mri-normal-brain',
 'No restricted diffusion on DWI to suggest acute infarction. No abnormal signal intensity on T1W, T2W, or FLAIR sequences. No enhancing lesion following gadolinium administration. The ventricles are normal in size and configuration. No mass effect, midline shift, or herniation. The major intracranial flow voids are preserved. The corpus callosum is normal. The posterior fossa structures are unremarkable. The paranasal sinuses and mastoid air cells are clear.',
 'neuro', 'Normal MRI brain — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/mri-normal-knee',
 'The medial and lateral menisci are intact with normal morphology and signal. The ACL and PCL are intact with normal signal and course. The MCL and LCL are intact. The articular cartilage of the medial and lateral compartments and patellofemoral joint is preserved without focal chondral defect. No bone marrow oedema. No significant joint effusion. No Baker cyst. Hoffa fat pad is normal.',
 'msk', 'Normal MRI knee — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/mri-normal-shoulder',
 'The supraspinatus, infraspinatus, subscapularis, and teres minor tendons are intact with normal signal and morphology. No rotator cuff tear. The long head of biceps tendon is in normal position within the bicipital groove with intact signal. The glenoid labrum is intact anteriorly, posteriorly, and superiorly. No SLAP lesion. No significant glenohumeral joint effusion. No subacromial-subdeltoid bursitis. The acromioclavicular joint is normal. Subacromial space is adequate.',
 'msk', 'Normal MRI shoulder — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/mri-normal-lspine',
 'Normal lumbar alignment with preservation of lordosis. Vertebral body heights and marrow signal are normal at all levels. No compression fracture or Modic changes. The intervertebral disc spaces are maintained with normal signal at all levels. No disc herniation or significant canal stenosis. Neural foramina are patent bilaterally at all levels. The conus medullaris terminates normally at the L1 level. The cauda equina nerve roots are of normal signal and course. The thecal sac is of adequate calibre.',
 'spine', 'Normal MRI lumbar spine — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/mri-normal-cspine',
 'Normal cervical alignment with preservation of lordosis. Vertebral body heights and marrow signal are normal C1 to T1. No fracture or Modic change. The intervertebral disc spaces are maintained with normal signal at all levels. No disc herniation, neural foraminal compromise, or significant central canal stenosis. The cervical spinal cord shows normal calibre and signal throughout without myelopathic change. The cerebellar tonsils are at normal position.',
 'spine', 'Normal MRI cervical spine — complete findings paragraph', 0),

-- X-RAY MACROS
('00000000-0000-0000-0000-000000000000',
 '/xr-normal-chest',
 'The lungs are clear bilaterally without focal consolidation, pleural effusion, or pneumothorax. The cardiac silhouette is not enlarged with a normal cardiothoracic ratio. The mediastinal contour is unremarkable and the trachea is central. Both hemidiaphragms are normally positioned with sharp costophrenic angles. The ribs, clavicles, and visible thoracic spine are intact. No soft tissue abnormality.',
 'chest', 'Normal chest X-ray — complete findings paragraph', 0),

('00000000-0000-0000-0000-000000000000',
 '/xr-normal-abdomen',
 'Non-dilated bowel gas pattern with gas present throughout the colon to the rectum. No small bowel dilatation. No radiological evidence of obstruction. No free intraperitoneal gas. No abnormal calcification. Both psoas shadows are visible. No significant soft tissue mass. The osseous structures are intact.',
 'abdomen', 'Normal abdominal X-ray', 0),

('00000000-0000-0000-0000-000000000000',
 '/xr-normal-knee',
 'No fracture or dislocation. The joint spaces of the medial, lateral, and patellofemoral compartments are preserved without joint space narrowing. No significant osteophyte formation. No subchondral sclerosis or cyst. No calcification of the menisci or articular cartilage. No significant joint effusion. Osseous structures are intact.',
 'msk', 'Normal knee X-ray', 0),

('00000000-0000-0000-0000-000000000000',
 '/xr-normal-hip',
 'No fracture or dislocation. The hip joint space is preserved bilaterally without significant narrowing. Normal femoral head morphology bilaterally. Acetabular contour is normal. No subchondral sclerosis, cyst, or significant osteophyte formation. Bone density is normal. No periarticular calcification.',
 'msk', 'Normal hip X-ray — bilateral', 0),

('00000000-0000-0000-0000-000000000000',
 '/xr-normal-ls',
 'Normal lumbar alignment with preserved lordosis. Vertebral body heights are maintained at all levels without compression fracture. The intervertebral disc spaces are preserved without significant disc height loss. No significant osteophyte formation. Facet joints are normal. The sacroiliac joints are symmetric and normal. Pedicles and posterior elements are intact. No lytic or sclerotic lesion.',
 'spine', 'Normal lumbar spine X-ray', 0)

ON CONFLICT (user_id, trigger) DO NOTHING;